#!/usr/bin/env node
// Condense a captured conversation JSONL into a compact analysis view.
import { createInterface } from 'node:readline';

const rl = createInterface({ input: process.stdin, crlfDelay: Infinity });
const entries = [];
for await (const line of rl) {
  if (!line.trim()) continue;
  try { entries.push(JSON.parse(line)); } catch { /* skip */ }
}

const t = (e) => (e.timestamp ? Date.parse(e.timestamp) : null);
const first = entries.find(t), last = [...entries].reverse().find(t);
const dur = first && last ? (t(last) - t(first)) / 1000 : 0;

const txt = (c) => Array.isArray(c)
  ? c.filter(b => b.type === 'text').map(b => b.text).join('\n')
  : (typeof c === 'string' ? c : '');
const clip = (s, n) => { s = (s || '').replace(/\s+/g, ' ').trim(); return s.length > n ? s.slice(0, n) + ' …' : s; };

const out = [];
out.push(`ENTRIES=${entries.length} SPAN=${first?.timestamp}..${last?.timestamp} DUR=${dur.toFixed(0)}s`);

// token usage totals
let outTok = 0, inTok = 0;
for (const e of entries) { const u = e.message?.usage; if (u) { outTok += u.output_tokens || 0; inTok += (u.input_tokens || 0) + (u.cache_read_input_tokens || 0); } }
out.push(`TOKENS out=${outTok} in(incl cache)=${inTok}`);

// tool call inventory
const tools = {};
for (const e of entries) {
  const c = e.message?.content;
  if (Array.isArray(c)) for (const b of c) if (b.type === 'tool_use') tools[b.name] = (tools[b.name] || 0) + 1;
}
out.push('TOOLS ' + Object.entries(tools).sort((a, b) => b[1] - a[1]).map(([k, v]) => `${k}:${v}`).join(' '));

// map tool_use_id -> {name, input summary, ts}
const uses = new Map();
for (const e of entries) {
  const c = e.message?.content;
  if (Array.isArray(c)) for (const b of c) if (b.type === 'tool_use') {
    let sum = '';
    const i = b.input || {};
    if (i.command) sum = i.command; else if (i.file_path) sum = i.file_path; else if (i.pattern) sum = i.pattern;
    else if (i.prompt) sum = i.prompt; else sum = JSON.stringify(i);
    uses.set(b.id, { name: b.name, sum: clip(sum, 160), ts: t(e) });
  }
}

out.push('\n=== HUMAN/DISPATCH TURNS ===');
for (const e of entries) {
  if (e.type !== 'user') continue;
  const c = e.message?.content;
  const s = txt(c);
  if (!s) continue;
  if (e.isMeta) continue;
  out.push(`[${e.timestamp}] ${clip(s, 700)}`);
}

out.push('\n=== TOOL ERRORS ===');
let errN = 0;
for (const e of entries) {
  const c = e.message?.content;
  if (!Array.isArray(c)) continue;
  for (const b of c) {
    if (b.type === 'tool_result' && b.is_error) {
      errN++;
      const u = uses.get(b.tool_use_id) || {};
      const body = typeof b.content === 'string' ? b.content : JSON.stringify(b.content);
      out.push(`[${e.timestamp}] ${u.name}: ${clip(u.sum, 120)}\n   ERR: ${clip(body, 300)}`);
    }
  }
}
out.push(`(total errors: ${errN})`);

out.push('\n=== LONG GAPS (>45s between consecutive entries) ===');
for (let i = 1; i < entries.length; i++) {
  const a = t(entries[i - 1]), b = t(entries[i]);
  if (!a || !b) continue;
  const g = (b - a) / 1000;
  if (g > 45) {
    // what tool was running
    const c = entries[i].message?.content;
    let what = entries[i].type;
    if (Array.isArray(c)) for (const bl of c) {
      if (bl.type === 'tool_result') { const u = uses.get(bl.tool_use_id) || {}; what = `result of ${u.name}: ${clip(u.sum, 110)}`; }
      else if (bl.type === 'tool_use') what = `tool_use ${bl.name}: ${clip(JSON.stringify(bl.input), 110)}`;
    }
    out.push(`+${g.toFixed(0)}s @${entries[i].timestamp} <- ${what}`);
  }
}

out.push('\n=== ASSISTANT TEXT TURNS ===');
for (const e of entries) {
  if (e.type !== 'assistant') continue;
  const s = txt(e.message?.content);
  if (!s.trim()) continue;
  out.push(`[${e.timestamp}] ${clip(s, 500)}`);
}

console.log(out.join('\n'));

